INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mercs-europe', 'Master System', 'Mercs (Europe)', '1991', 'Action', 'Capcom', '2', 'Arcade', 'Top-down run and gun shooter.', 'Infiltrate enemy territory and rescue the President.', 'High-octane arcade shooting action.', 'Mercs delivers intense vertical-scrolling combat. As a member of an elite mercenary squad, use a variety of heavy weaponry and power-ups to blast through enemy lines in this faithful 8-bit conversion of the Capcom classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('michael-jacksons-moonwalker-usa-europe', 'Master System', 'Michael Jackson''s Moonwalker (USA, Europe)', '1989', 'Action', 'Sega', '2', 'Music', 'Side-scrolling action platformer.', 'Rescue children and defeat Mr. Big using dance moves.', 'Iconic action game based on Michael Jackson''s film.', 'Moonwalker features the King of Pop in a stylized battle against crime. Use signature dance moves to defeat enemies and explore urban environments in this rhythm-infused platformer with a legendary 8-bit soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mick-&-mack-as-the-global-gladiators-europe', 'Master System', 'Mick & Mack as the Global Gladiators (Europe)', '1992', 'Platform', 'Virgin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Clean up pollution and reach the goal.', 'A fast-paced McDonald''s branded environmental quest.', 'Global Gladiators is a visually stunning late-era title. Help Mick and Mack use their slime-shooters to battle pollution monsters across vibrant worlds in this fluidly animated and challenging platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mickeys-ultimate-challenge-brazil', 'Master System', 'Mickey''s Ultimate Challenge (Brazil)', '1994', 'Puzzle', 'Sega', '1', 'Cartoon', 'Puzzle-solving adventure.', 'Complete logic and memory games to find the beans.', 'A brain-teasing Disney adventure for all ages.', 'Mickey''s Ultimate Challenge brings a collection of clever mini-games to the Master System. Solve puzzles in a fairy-tale kingdom to earn magic beans and uncover the mystery of the strange clouds.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('micro-machines-europe', 'Master System', 'Micro Machines (Europe)', '1993', 'Racing', 'Codemasters', '2', 'Arcade', 'Top-down miniature racing.', 'Finish first on creative household tracks.', 'Frantic racing with tiny cars in everyday settings.', 'Micro Machines is a masterpiece of 8-bit racing. Compete on breakfast tables and bathtubs, navigating obstacles and outperforming rivals in this highly addictive and technically impressive miniature racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-warriors---seal-of-the-dark-lord-usa-europe', 'Master System', 'Miracle Warriors - Seal of the Dark Lord (USA, Europe)', '1987', 'RPG', 'Sega', '1', 'Fantasy', 'First-person dungeon crawling RPG.', 'Recruit three companions and defeat the Dark Lord.', 'An epic and expansive early 8-bit RPG.', 'Miracle Warriors offers a massive world map and challenging first-person dungeons. Master the turn-based combat and manage your party''s reputation to restore peace to the land in this deep fantasy quest.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('miracle-warriors---seal-of-the-dark-lord-usa-europe-beta', 'Master System', 'Miracle Warriors - Seal of the Dark Lord (USA, Europe) (Beta)', '1987', 'RPG', 'Sega', '1', 'Fantasy', 'First-person dungeon crawling RPG.', 'Recruit three companions and defeat the Dark Lord.', 'Beta version of the sprawling fantasy RPG.', 'Experience the early build of Miracle Warriors. This version showcases the foundational turn-based combat and exploration mechanics that made the final release a landmark title for RPG fans on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('missile-defense-3-d-usa-europe', 'Master System', 'Missile Defense 3-D (USA, Europe)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'First-person 3D shooting gallery.', 'Intercept nuclear missiles before they hit the city.', 'High-stakes defense using Sega 3D Glasses.', 'Missile Defense 3-D utilizes 3D technology to create an immersive sky-view combat experience. Aim and fire with precision to stop waves of incoming missiles in this intense and unique hardware showcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monica-no-castelo-do-dragao-brazil', 'Master System', 'Monica no Castelo do Dragao (Brazil)', '1991', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Use your sword to defeat the dragon and save the day.', 'A Brazilian re-skin of Wonder Boy in Monster Land.', 'Mônica no Castelo do Dragão features the beloved Brazilian comic character. Explore a fantasy world, buy gear, and battle mythical creatures in this legendary localized version of a Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa-europe', 'Master System', 'Monopoly (USA, Europe)', '1988', 'Board', 'Parker Brothers', '4', 'Board', 'Board game simulation.', 'Bankrupt your opponents by buying properties.', 'A faithful 8-bit digital version of the board game.', 'Monopoly brings the classic property-trading game to the Master System. Featuring animated tokens and varied computer difficulties, it offers a complete strategic experience for up to four players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('monopoly-usa', 'Master System', 'Monopoly (USA)', '1988', 'Board', 'Parker Brothers', '4', 'Board', 'Board game simulation.', 'Bankrupt your opponents by buying properties.', 'North American release of the classic property game.', 'Trade, build houses, and collect rent in this US version of Monopoly. The game perfectly translates the tabletop strategy to the 8-bit screen with clear visuals and smooth turn-based gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('montezumas-revenge-featuring-panama-joe-usa', 'Master System', 'Montezuma''s Revenge Featuring Panama Joe (USA)', '1984', 'Platform', 'Utopia Software', '1', 'Adventure', 'Multi-level room-based platformer.', 'Find the treasure while avoiding traps and skulls.', 'A challenging pyramid-climbing adventure.', 'Montezuma''s Revenge (featuring Panama Joe) is a pioneer of the action-adventure genre. Navigate a deadly Aztec temple, collect keys, and master precise jumps to claim the ultimate treasure in this retro classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-europe', 'Master System', 'Mortal Kombat (Europe)', '1993', 'Fighting', 'Midway', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat Shang Tsung in the tournament of champions.', 'A blood-pumping 8-bit port of the arcade hit.', 'Mortal Kombat brings the legendary fighters to the Master System. Execute special moves and fatalities in this impressive conversion that maintains the dark atmosphere and competitive spirit of the original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-3-brazil', 'Master System', 'Mortal Kombat 3 (Brazil)', '1996', 'Fighting', 'Midway', '2', 'Arcade', 'One-on-one fighting game.', 'Win the final battle against Shao Kahn.', 'A rare 8-bit port of the third MK entry.', 'Mortal Kombat 3 on the Master System is a technical feat from the Brazilian market. Featuring a varied roster and the series'' signature fast-paced combat, it offers a brutal 1v1 experience for late-gen fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('mortal-kombat-ii-europe', 'Master System', 'Mortal Kombat II (Europe)', '1994', 'Fighting', 'Midway', '2', 'Arcade', 'One-on-one fighting game.', 'Travel to Outworld and defeat Shao Kahn.', 'A fluid and colorful sequel to the fighting hit.', 'Mortal Kombat II features more characters and refined controls. Battle through diverse arenas and master the improved combo system in this high-quality 8-bit fighting game conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ms-pac-man-europe', 'Master System', 'Ms. Pac-Man (Europe)', '1990', 'Arcade', 'Namco', '2', 'Classic', 'Fixed-screen maze navigator.', 'Eat all the pellets while avoiding the ghosts.', 'A polished home version of the arcade sequel.', 'Ms. Pac-Man offers the classic fruit-munching gameplay with multiple maze layouts. Experience the speed and charm of the arcade original on your Master System with smooth animation and iconic sound effects.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('my-hero-usa-europe', 'Master System', 'My Hero (USA, Europe)', '1985', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue your girlfriend from the street gang.', 'A fast-paced and challenging urban brawler.', 'My Hero features a relentless pace as you punch and kick your way through city streets. Face off against tough bosses and avoid hazards in this early Sega classic that rewards quick reflexes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('nekkyuu-koushien-japan', 'Master System', 'Nekkyuu Koushien (Japan)', '1988', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the high school baseball championship.', 'A Japanese exclusive high-school baseball sim.', 'Nekkyuu Koushien focuses on the passion of youth baseball. Manage your team and execute perfect plays to climb the tournament brackets in this culturally rich and mechanically sound 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('new-zealand-story-the-europe', 'Master System', 'New Zealand Story, The (Europe)', '1988', 'Platform', 'Taito', '2', 'Cute', 'Side-scrolling platformer.', 'Rescue your friends across different lands.', 'A whimsical and colorful arcade conversion.', 'The New Zealand Story features Wiki the kiwi in a massive, vibrant world. Use various weapons and vehicles to navigate trap-filled levels and save your fellow birds in this charming and difficult adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-japan', 'Master System', 'Ninja (Japan)', '1986', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Infiltrate the castle and defeat the evil ninja.', 'The original Japanese version of The Ninja.', 'Ninja (Japan) features intense overhead and side-scrolling action. Master the use of shurikens and stealth as you battle waves of enemy ninjas to rescue the princess in this early Sega masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden-europe', 'Master System', 'Ninja Gaiden (Europe)', '1992', 'Action', 'Tecmo', '1', 'Ninja', 'Side-scrolling action platformer.', 'Recover the dragon sword and avenge your father.', 'A legendary and difficult cinematic ninja quest.', 'Ninja Gaiden on the Master System is a unique title distinct from the NES version. Featuring smooth wall-jumping and fast-paced swordplay, Ryu Hayabusa must navigate treacherous stages and face massive bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-gaiden-europe-beta', 'Master System', 'Ninja Gaiden (Europe) (Beta)', '1992', 'Action', 'Tecmo', '1', 'Ninja', 'Side-scrolling action platformer.', 'Recover the dragon sword and avenge your father.', 'Beta version of the cinematic ninja action game.', 'Experience the development of Ryu''s 8-bit quest. This Beta version of Ninja Gaiden offers a look at the level design and combat mechanics that made the final European release a highly sought-after classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ninja-the-usa-europe', 'Master System', 'Ninja, The (USA, Europe)', '1986', 'Action', 'Sega', '1', 'Ninja', 'Top-down action shooter.', 'Infiltrate the castle and defeat the evil ninja.', 'The international release of the stealth-actioner.', 'The Ninja features challenging overhead combat. Use your invisibility powers and master the trajectory of your shurikens to navigate through enemy-filled forests and castles in this 8-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-gold-europe-enfrdeesitnlptsv', 'Master System', 'Olympic Gold (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1992', 'Sports', 'Sega', '4', 'Olympic', 'Multi-event sports simulation.', 'Win the gold medal in the Barcelona ''92 events.', 'The official licensed game of the 1992 Olympics.', 'Olympic Gold features events like 100m sprint, archery, and swimming. With three difficulty levels and a focus on timing and button-mashing, it offers a highly competitive and polished sports experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('olympic-gold-korea-enfrdeesitnlptsv', 'Master System', 'Olympic Gold (Korea) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1992', 'Sports', 'Sega', '4', 'Olympic', 'Multi-event sports simulation.', 'Win the gold medal in the Barcelona ''92 events.', 'Korean edition of the official Olympic game.', 'Compete for glory in the Korean version of Olympic Gold. Master the various athletic disciplines and climb the podium in this international sports title that pushed the boundaries of 8-bit animation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('opa-opa-japan', 'Master System', 'Opa Opa (Japan)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Defend the solar system from invaders.', 'A unique spin-off featuring the Fantasy Zone hero.', 'Opa Opa (known as Fantasy Zone: The Maze in some regions) features top-down maze navigation and shooting. Collect coins to buy weapon upgrades and clear dozens of colorful, enemy-filled rooms.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('operation-wolf-europe', 'Master System', 'Operation Wolf (Europe)', '1989', 'Shooter', 'Taito', '1', 'Arcade', 'First-person light gun shooter.', 'Rescue hostages and escape the enemy base.', 'A high-tension arcade shooting conversion.', 'Operation Wolf is a masterpiece of light gun action. Compatible with the Light Phaser, you must manage your ammo and grenades while blasting through jungle and prison camps to complete your rescue mission.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ottifants-the-europe-enfrdeesit', 'Master System', 'Ottifants, The (Europe) (En,Fr,De,Es,It)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the mysterious Ottifants and reach the goal.', 'A quirky and colorful cartoon platformer.', 'The Ottifants features Bruno in a series of imaginative levels. Use your trunk to shoot bubbles and solve puzzles in this late-release title known for its high-quality sprites and charming atmosphere.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-run-world', 'Master System', 'Out Run (World)', '1987', 'Racing', 'Sega', '2', 'Arcade', 'Behind-the-back racing.', 'Reach the finish line before the timer expires.', 'The definitive 8-bit port of the arcade legend.', 'Out Run brings the wind-in-your-hair racing experience home. Choose your music and your route through diverse landscapes in this iconic Ferrari-powered racer that defined a generation of Sega fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-run-3-d-europe', 'Master System', 'Out Run 3-D (Europe)', '1988', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back 3D racing.', 'Reach the checkpoints in a stereoscopic 3D world.', 'A special 3D version of the racing classic.', 'Out Run 3-D uses the Sega 3D Glasses to provide a sense of depth on the open road. Experience the classic gameplay with enhanced visuals and exclusive tracks designed specifically for the 3D hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('out-run-europa-europe', 'Master System', 'Out Run Europa (Europe)', '1991', 'Racing', 'Sega', '1', 'Arcade', 'Combat-based racing with multiple vehicles.', 'Pursue the villains across Europe using cars, bikes, and jetskis.', 'A high-speed pursuit racer with varied vehicle combat.', 'Out Run Europa takes the classic racing formula and adds a layer of intense combat. Dodge enemy fire and use specialized weapons as you speed through iconic European cities in this action-packed 8-bit spin-off.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pac-mania-europe', 'Master System', 'Pac-Mania (Europe)', '1988', 'Arcade', 'Namco', '2', 'Classic', 'Isometric maze navigation.', 'Eat all dots while jumping over ghosts.', 'A 3D-perspective twist on the classic Pac-Man formula.', 'Pac-Mania brings the arcade sensation to the Master System. Featuring a vertical jump mechanic and colorful isometric graphics, navigate through various worlds while outsmarting Blinky, Pinky, Inky, and Clyde in this polished port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-europe', 'Master System', 'Paperboy (Europe)', '1988', 'Action', 'Atari Games', '1', 'Arcade', 'Isometric delivery simulation.', 'Deliver papers while avoiding neighborhood hazards.', 'A challenging arcade port of the iconic paper delivery game.', 'Paperboy tasks you with surviving a suburban gauntlet. Throw papers with precision and dodge dogs, cars, and breakdancers to keep your subscribers happy in this faithful and difficult 8-bit recreation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('paperboy-usa', 'Master System', 'Paperboy (USA)', '1988', 'Action', 'Atari Games', '1', 'Arcade', 'Isometric delivery simulation.', 'Deliver papers while avoiding neighborhood hazards.', 'North American release of the paper delivery classic.', 'Experience the suburban chaos of Paperboy in this US version. Master the timing of your throws and learn the patterns of the neighborhood to achieve the high score and survive a full week on the job.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('parlour-games-usa-europe', 'Master System', 'Parlour Games (USA, Europe)', '1987', 'Board', 'Sega', '2', 'Board', 'Multi-game logic and sports compilation.', 'Win at Billiards, Darts, and World Bingo.', 'A collection of classic indoor parlor games.', 'Parlour Games offers a relaxing break from the action. Compete against the computer or friends in highly accurate simulations of pool and darts, featuring smooth physics and multiple tournament modes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pat-riley-basketball-usa-proto', 'Master System', 'Pat Riley Basketball (USA) (Proto)', '1990', 'Sports', 'Virgin Interactive', '2', 'Basketball', 'Sports simulation.', 'Lead your basketball team to victory.', 'Prototype version of the Pat Riley endorsed basketball sim.', 'This rare prototype of Pat Riley Basketball offers a look at the development of the 8-bit hoops title. Master the timing of shots and defensive plays in this early build of the professional sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('penguin-land-usa-europe', 'Master System', 'Penguin Land (USA, Europe)', '1987', 'Platform', 'Sega', '1', 'Cute', 'Physics-based puzzle platformer.', 'Guide the egg safely to the bottom of the stage.', 'A strategic puzzle game featuring a space penguin.', 'Penguin Land is a cult classic that rewards careful planning. Dig through blocks and use gravity to transport your fragile egg through a series of increasingly complex and dangerous underground mazes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pga-tour-golf-europe', 'Master System', 'PGA Tour Golf (Europe)', '1991', 'Sports', 'Electronic Arts', '1', 'Simulation', 'Sports simulation (Golf).', 'Win the PGA tournament with the lowest score.', 'A professional-grade golf simulation for the 8-bit era.', 'PGA Tour Golf brings real-world strategy to the Master System. Account for wind, slope, and club selection as you compete on legendary courses in this deeply mechanical and rewarding sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-brazil', 'Master System', 'Phantasy Star (Brazil)', '1991', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based JRPG.', 'Assemble a team to overthrow the tyrant Lassic.', 'The legendary Brazilian release of the first Phantasy Star.', 'Phantasy Star is the crown jewel of the Master System. Explore vast planets and navigate groundbreaking 3D dungeons in this expansive sci-fi epic that defined the JRPG genre for Sega fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-japan', 'Master System', 'Phantasy Star (Japan)', '1987', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based JRPG.', 'Assemble a team to overthrow the tyrant Lassic.', 'The original Japanese masterpiece of sci-fi role-playing.', 'Experience the roots of the Phantasy Star saga. Featuring incredible 8-bit graphics and a deep narrative, Alis Landale’s journey through the Algol Star System remains a technical and storytelling marvel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-japan-en-by-sms-power-v102', 'Master System', 'Phantasy Star (Japan) [En by SMS Power v1.02]', '1987', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based JRPG.', 'Assemble a team to overthrow the tyrant Lassic.', 'Fan-translated version of the Japanese original.', 'This localized version of the Japanese Phantasy Star allows players to enjoy the original mechanics and script with modern English text, preserving the authentic 8-bit RPG experience for Western audiences.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-korea', 'Master System', 'Phantasy Star (Korea)', '1989', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based JRPG.', 'Assemble a team to overthrow the tyrant Lassic.', 'Rare Korean edition of the landmark sci-fi RPG.', 'Phantasy Star (Korea) brings the epic struggle against Lassic to the local market. Explore dungeons and build your party in this high-quality translation of one of the most influential RPGs ever made.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-usa-europe-v12', 'Master System', 'Phantasy Star (USA, Europe) (v1.2)', '1987', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based JRPG.', 'Assemble a team to overthrow the tyrant Lassic.', 'Revised international version of the sci-fi epic.', 'Phantasy Star v1.2 offers the complete, polished experience of Alis''s adventure. With its battery backup for saving and massive world map, it stands as a testament to the power of the Master System hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('phantasy-star-usa-europe-v13', 'Master System', 'Phantasy Star (USA, Europe) (v1.3)', '1987', 'RPG', 'Sega', '1', 'Fantasy', 'Turn-based JRPG.', 'Assemble a team to overthrow the tyrant Lassic.', 'Final refined version of the legendary 8-bit RPG.', 'This version 1.3 of Phantasy Star provides minor bug fixes to the international release. Journey across Palma, Motavia, and Dezoris in the most stable version of this groundbreaking sci-fi adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pit-fighter-brazil', 'Master System', 'Pit Fighter (Brazil)', '1991', 'Fighting', 'Midway', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat all rivals in a brutal underground tournament.', 'A gritty arcade port of the digitized brawler.', 'Pit Fighter on the Master System captures the raw energy of the arcade original. Choose your fighter and use environmental objects to pummel your way to the top in this rare Brazilian-release brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pit-fighter-europe', 'Master System', 'Pit Fighter (Europe)', '1991', 'Fighting', 'Midway', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat all rivals in a brutal underground tournament.', 'European edition of the gritty street-fighting game.', 'Engage in brutal 1v1 combat in the European version of Pit Fighter. Use combos and special moves to defeat a variety of unique opponents in a quest to become the ultimate underground champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('populous-europe', 'Master System', 'Populous (Europe)', '1989', 'Strategy', 'Bullfrog Productions', '1', 'God Game', 'God-simulation strategy.', 'Lead your followers to victory against rival gods.', 'A deep and influential strategy game by Peter Molyneux.', 'Populous allows you to shape the earth and influence your followers'' growth. Use divine powers to conquer territory and defeat enemy tribes in this impressive 8-bit port of the strategy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('poseidon-wars-3-d-usa-europe', 'Master System', 'Poseidon Wars 3-D (USA, Europe)', '1989', 'Shooter', 'Sega', '1', 'Arcade', 'Behind-the-back naval rail shooter.', 'Protect your fleet and destroy enemy vessels.', 'A 3D naval combat game for Sega''s 3D Glasses.', 'Poseidon Wars 3-D uses stereoscopic depth to bring ocean combat to life. Navigate through dangerous waters and use your radar to lock onto and destroy enemy ships and aircraft in this unique hardware showcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-strike-usa-europe', 'Master System', 'Power Strike (USA, Europe)', '1988', 'Shooter', 'Compile', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the enemy fleet and save the world.', 'A high-speed, intense vertical shooting masterpiece.', 'Power Strike (Aleste) is famous for its incredible speed and weapon variety. Battle through waves of bio-mechanical enemies in one of the most technically impressive and difficult shooters on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('power-strike-ii-europe', 'Master System', 'Power Strike II (Europe)', '1993', 'Shooter', 'Compile', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Stop the aerial pirates and destroy their sky fortress.', 'A late-release sequel with incredible 8-bit visuals.', 'Power Strike II is a Master System exclusive and a graphical tour de force. Featuring sophisticated weaponry and massive bosses, it is widely considered one of the finest "shmups" ever created for 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('predator-2-europe', 'Master System', 'Predator 2 (Europe)', '1991', 'Action', 'Probe Software', '1', 'Movie', 'Side-scrolling action shooter.', 'Hunt the Predator through urban and jungle levels.', 'A tense action game based on the sci-fi sequel.', 'Predator 2 puts you in the role of Detective Harrigan. Use a variety of futuristic weapons to track down the alien hunter while navigating dangerous city streets in this atmospheric 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('prince-of-persia-europe', 'Master System', 'Prince of Persia (Europe)', '1992', 'Platform', 'Broderbund', '1', 'Classic', 'Cinematic side-scrolling platformer.', 'Rescue the Princess from the Vizier Jaffar.', 'A fluidly animated port of the classic adventure.', 'Prince of Persia on the Master System features the rotoscoped animation that made the original a hit. Navigate deadly traps and engage in sword duels in a race against the 60-minute time limit.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-wrestling-usa-europe', 'Master System', 'Pro Wrestling (USA, Europe)', '1986', 'Wrestling', 'Sega', '2', 'Arcade', 'Professional wrestling simulation.', 'Win the world championship belt.', 'A classic 8-bit wrestling game with diverse characters.', 'Pro Wrestling features a colorful roster of wrestlers, each with unique signature moves. Master the timing of grapples and strikes to win the crowd and the title in this foundational Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('pro-yakyuu-pennant-race-the-japan', 'Master System', 'Pro Yakyuu Pennant Race, The (Japan)', '1987', 'Sports', 'Sega', '1', 'Baseball', 'Sports simulation (Baseball).', 'Win the Pennant Race championship.', 'A detailed Japanese exclusive baseball simulation.', 'The Pro Yakyuu Pennant Race offers a deep look at the sport, focusing on team management and precise batting mechanics. Experience the excitement of the Japanese league in this polished 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psychic-world-europe', 'Master System', 'Psychic World (Europe)', '1989', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling action adventure.', 'Use elemental powers to save the world.', 'A unique platformer featuring a psychic protagonist.', 'Psychic World tasks you with mastering various psychic abilities—like fire, ice, and levitation—to navigate levels. This visually impressive port offers deep gameplay and strategic character building.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('psycho-fox-usa-europe', 'Master System', 'Psycho Fox (USA, Europe)', '1989', 'Platform', 'Vic Tokai', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat the evil Madfox Daigoro and his minions.', 'A charming platformer with character-swapping mechanics.', 'Psycho Fox is a Master System favorite known for its physics and variety. Swap between different animal characters to utilize their unique strengths in this colorful and highly original adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putt-&-putter-europe', 'Master System', 'Putt & Putter (Europe)', '1991', 'Sports', 'Sanritsu Denki', '2', 'Golf', 'Isometric golf puzzle.', 'Sink the ball into the hole using the fewest moves.', 'A creative blend of golf and puzzle mechanics.', 'Putt & Putter (known as Zany Golf) takes the sport to surreal levels. Navigate through obstacle-filled courses that require both precision and logic to solve in this charming and addictive isometric title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('putt-&-putter-europe-beta', 'Master System', 'Putt & Putter (Europe) (Beta)', '1991', 'Sports', 'Sanritsu Denki', '2', 'Golf', 'Isometric golf puzzle.', 'Sink the ball into the hole using the fewest moves.', 'Beta version of the creative golf-puzzle hybrid.', 'This Beta version of Putt & Putter offers an early look at the game''s unique level design. Test your aim and problem-solving skills across a variety of bizarre miniature golf courses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quartet-usa-europe', 'Master System', 'Quartet (USA, Europe)', '1986', 'Action', 'Sega', '4', 'Arcade', 'Side-scrolling action shooter.', 'Defeat the enemy and rescue your teammates.', 'A fast-paced arcade port with jetpack mechanics.', 'Quartet features high-flying action as you navigate through mechanical corridors. Use your jetpack to gain a tactical advantage and defeat massive bosses in this colorful and frantic 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('quest-for-the-shaven-yak-starring-ren-hoek-&-stimpy-brazil', 'Master System', 'Quest for the Shaven Yak Starring Ren Hoek & Stimpy (Brazil)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the Shaven Yak and complete the gross-out quest.', 'A wacky platformer based on the Nicktoon classic.', 'Quest for the Shaven Yak brings the surreal humor of Ren & Stimpy to the Master System. Navigate through bizarre levels and face off against gross-out villains in this rare and vibrant Brazilian exclusive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('r-type-world', 'Master System', 'R-Type (World)', '1988', 'Shooter', 'Irem', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Destroy the Bydo Empire and its bio-mechanical core.', 'A legendary arcade port of the definitive sci-fi shmup.', 'R-Type on the Master System is a technical masterpiece. Utilize the "Force" pod for both offense and defense as you navigate through iconic levels and face massive bosses in this pixel-perfect 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rc-grand-prix-usa-europe', 'Master System', 'R.C. Grand Prix (USA, Europe)', '1990', 'Racing', 'Sega', '1', 'Arcade', 'Isometric racing simulation.', 'Win the R.C. championship and upgrade your car.', 'A competitive remote-control car racing game.', 'R.C. Grand Prix features tight isometric handling and a deep upgrade system. Compete against rival cars on varied tracks, managing your acceleration and braking to become the ultimate radio-controlled champion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rainbow-islands---the-story-of-bubble-bobble-2-brazil', 'Master System', 'Rainbow Islands - The Story of Bubble Bobble 2 (Brazil)', '1993', 'Platform', 'Taito', '1', 'Cartoon', 'Vertical-climbing platformer.', 'Create rainbows to climb levels and defeat bosses.', 'The colorful and whimsical sequel to Bubble Bobble.', 'Rainbow Islands (Brazil) brings the arcade magic of Bub and Bob to the Master System. Use rainbows as both platforms and weapons to ascend through island-themed stages in this vibrant and highly addictive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rainbow-islands---the-story-of-bubble-bobble-2-europe', 'Master System', 'Rainbow Islands - The Story of Bubble Bobble 2 (Europe)', '1990', 'Platform', 'Taito', '1', 'Cartoon', 'Vertical-climbing platformer.', 'Create rainbows to climb levels and defeat bosses.', 'European edition of the classic rainbow-climbing sequel.', 'Experience the legend of Rainbow Islands. Master the unique rainbow-mechanic to find secret items and defeat the massive bosses at the top of each island in this polished and cheerful 8-bit platforming classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rambo---first-blood-part-ii-usa', 'Master System', 'Rambo - First Blood Part II (USA)', '1985', 'Action', 'Sega', '1', 'Movie', 'Top-down run and gun shooter.', 'Infiltrate enemy camps and rescue POWs.', 'High-octane action based on the classic Stallone film.', 'Rambo: First Blood Part II delivers intense overhead shooting action. Use your machine gun and explosive arrows to clear out enemy bases and rescue captives in this quintessential 8-bit military shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rambo-iii-usa-europe', 'Master System', 'Rambo III (USA, Europe)', '1989', 'Action', 'Sega', '1', 'Movie', 'Light gun / Rail shooter.', 'Infiltrate the Soviet base and rescue Colonel Trautman.', 'An intense shooter compatible with the Light Phaser.', 'Rambo III takes the action to Afghanistan. Use your light gun to blast through enemy soldiers and tanks in this cinematic arcade port that features high-speed rail-shooting and impressive 8-bit visuals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampage-usa-europe', 'Master System', 'Rampage (USA, Europe)', '1988', 'Action', 'Data East', '2', 'Arcade', 'Side-scrolling monster simulation.', 'Destroy buildings and eat civilians while avoiding the army.', 'A chaotic city-smashing arcade conversion.', 'Rampage lets you play as George, Lizzie, or Ralph. Scale skyscrapers and punch them into rubble while fending off helicopters and tanks in this fun and destructive 8-bit monster romp.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rampart-europe', 'Master System', 'Rampart (Europe)', '1990', 'Strategy', 'Atari Games', '2', 'Arcade', 'Strategy and puzzle combat.', 'Build fortifications and destroy enemy ships.', 'A unique mix of Tetris-style building and naval combat.', 'Rampart challenges your speed and strategy. Rebuild your castle walls under a time limit and position your cannons to sink invading fleets in this highly addictive and original arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rastan-usa-europe', 'Master System', 'Rastan (USA, Europe)', '1988', 'Action', 'Taito', '1', 'Arcade', 'Side-scrolling hack and slash.', 'Defeat the dragon and rescue the princess.', 'A brutal and epic barbarian action game.', 'Rastan is a landmark title for the Master System. Armed with various weapons, navigate through dangerous terrain and master the difficult combat to survive this dark and atmospheric fantasy classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('reggie-jackson-baseball-usa', 'Master System', 'Reggie Jackson Baseball (USA)', '1988', 'Sports', 'Sega', '2', 'Baseball', 'Sports simulation (Baseball).', 'Win the league championship with Reggie Jackson.', 'A professional baseball sim with licensed branding.', 'Reggie Jackson Baseball offers multiple modes, including exhibition and tournament. With its focus on timing and team stats, it provides a solid and competitive baseball experience for 8-bit sports fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('renegade-europe', 'Master System', 'Renegade (Europe)', '1988', 'Beat ''em up', 'Taito', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue your girlfriend from the street gang.', 'A gritty and difficult urban combat brawler.', 'Renegade features a more realistic take on the street-brawler genre. Use punches, kicks, and throws to clear out subway stations and docks in this challenging port of the arcade original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rescue-mission-usa-europe', 'Master System', 'Rescue Mission (USA, Europe)', '1989', 'Shooter', 'Sega', '1', 'Arcade', 'Light gun shooting gallery.', 'Protect the medic as he rescues wounded soldiers.', 'A unique protective shooter for the Light Phaser.', 'Rescue Mission tasks you with clearing a path for a specialized medic. Aim with precision to take down snipers and traps in this creative light gun title that requires both speed and tactical awareness.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('road-rash-europe', 'Master System', 'Road Rash (Europe)', '1992', 'Racing', 'Sega', '1', 'Arcade', 'Combat-based motorcycle racing.', 'Win the race while punching and kicking rivals.', 'The legendary 8-bit port of the biker combat hit.', 'Road Rash brings the speed and violence of the open road to the Master System. Upgrade your bike and survive the gauntlet of police and rival gangs in this high-energy, combat-driven racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-3-europe', 'Master System', 'RoboCop 3 (Europe)', '1992', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling action platformer.', 'Stop the OCP corporation and the Rehabs.', 'A dark action game based on the third film.', 'RoboCop 3 features the iconic cyborg cop in a struggle to save Detroit. Use diverse weapon upgrades and a jetpack to battle urban threats in this late-era title known for its impressive graphics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('robocop-versus-the-terminator-europe', 'Master System', 'RoboCop versus The Terminator (Europe)', '1993', 'Action', 'Virgin Interactive', '1', 'Sci-Fi', 'Side-scrolling action shooter.', 'Stop Skynet from launching the nuclear strike.', 'A brutal crossover of the two legendary sci-fi icons.', 'RoboCop versus The Terminator is a technical feat for the system. Navigate through high-tech facilities and use massive firepower to destroy the Terminator army in this dark and atmospheric shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('rocky-world', 'Master System', 'Rocky (World)', '1987', 'Sports', 'Sega', '2', 'Boxing', 'One-on-one boxing simulation.', 'Defeat Apollo Creed, Clubber Lang, and Ivan Drago.', 'A cinematic boxing game based on the movie saga.', 'Rocky features the legendary training montages and high-stakes matches of the films. Master your timing and stamina to knock out the world’s toughest boxers in this classic 8-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('running-battle-europe', 'Master System', 'Running Battle (Europe)', '1992', 'Action', 'Sims', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Defeat the "M" organization and save the world.', 'A futuristic brawler with a unique armor mechanic.', 'Running Battle features fast-paced combat and large character sprites. Battle through city streets and labs, utilizing power-ups to enhance your strength in this atmospheric and gritty late-gen action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sagaia-europe', 'Master System', 'Sagaia (Europe)', '1989', 'Shooter', 'Sega', '1', 'Arcade', 'Side-scrolling shoot ''em up.', 'Defeat the Galick Empire across multiple planets.', 'The Master System port of Darius II.', 'Sagaia features the iconic "fish" ships and branching paths of the Darius series. Experience intense multi-screen shooting action and massive boss fights in this technically impressive 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sangokushi-3-korea-unl', 'Master System', 'Sangokushi 3 (Korea) (Unl)', '1993', 'Strategy', 'Unlicensed', '1', 'Historical', 'Turn-based strategy.', 'Unify China under one banner.', 'A deep historical strategy game from Korea.', 'Sangokushi 3 (Romance of the Three Kingdoms) is a rare 8-bit strategy title. Manage resources, diplomacy, and military tactics to conquer territories in this complex and rewarding historical simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sapo-xule---o-mestre-do-kung-fu-brazil', 'Master System', 'Sapo Xule - O Mestre do Kung Fu (Brazil)', '1995', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling beat ''em up.', 'Defeat the master and rescue the princess.', 'A Brazilian re-skin of Kung Fu Kid starring Sapo Xulé.', 'Sapo Xulé: O Mestre do Kung Fu brings the popular Brazilian frog character to a classic martial arts adventure. Use your kicks and jumps to defeat enemies in this charming and localized 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sapo-xule---sos-lagoa-poluida-brazil', 'Master System', 'Sapo Xule - S.O.S Lagoa Poluida (Brazil)', '1995', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling platformer.', 'Clean the lake of pollution and defeat the villains.', 'A Brazilian re-skin of Astro Warrior.', 'Sapo Xulé: S.O.S. Lagoa Poluída transforms the space shooter Astro Warrior into an environmental underwater mission. Help Sapo Xulé clean the lake in this vibrant and fast-paced 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sapo-xule-vs-os-invasores-do-brejo-brazil', 'Master System', 'Sapo Xule vs. Os Invasores do Brejo (Brazil)', '1996', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling action platformer.', 'Stop the invaders and save the swamp.', 'A Brazilian re-skin of Psycho Fox.', 'Sapo Xulé vs. Os Invasores do Brejo features the physics-based gameplay of Psycho Fox with a local twist. Swap between different animal friends to navigate complex levels in this creative and colorful title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('satellite-7-japan', 'Master System', 'Satellite 7 (Japan)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the enemy space fleet and its mothership.', 'A fast-paced sci-fi shooter from Japan.', 'Satellite 7 delivers intense overhead action. Maneuver through asteroid fields and mechanical corridors, upgrading your weaponry to take down a massive intergalactic threat in this classic 8-bit shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('schtroumpfs-autour-du-monde-les-europe-enfrdees', 'Master System', 'Schtroumpfs Autour du Monde, Les (Europe) (En,Fr,De,Es)', '1996', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Travel across the globe to rescue your friends.', 'A late-era Smurfs adventure with diverse locations.', 'Les Schtroumpfs Autour du Monde features impressive graphics and varied gameplay. Guide the Smurfs through different continents, from the snowy North to the dry Savannah, in this polished Disney-style platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('schtroumpfs-autour-du-monde-les-europe-enfrdees-beta', 'Master System', 'Schtroumpfs Autour du Monde, Les (Europe) (En,Fr,De,Es) (Beta)', '1996', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Travel across the globe to rescue your friends.', 'Beta version of the global Smurfs adventure.', 'This Beta version of Les Schtroumpfs Autour du Monde offers a look into the development of this late-gen masterpiece. Test the platforming mechanics and explore the early level designs of this rare 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('scramble-spirits-europe', 'Master System', 'Scramble Spirits (Europe)', '1988', 'Shooter', 'Sega', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Defeat the enemy air force and sea fleet.', 'A cinematic military-themed aerial shooter.', 'Scramble Spirits features a unique "companion" mechanic where you can deploy smaller planes to assist you. Battle through intense enemy formations and massive bosses in this polished arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sdi-japan', 'Master System', 'SDI (Japan)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Missile-command style shooting.', 'Protect Earth from incoming nuclear missiles.', 'The original Japanese version of Global Defense.', 'SDI (Strategic Defense Initiative) is a high-speed orbital shooter. Use the cursor to target and destroy threats in space while defending the planet from a nuclear apocalypse in this tense arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('secret-command-europe', 'Master System', 'Secret Command (Europe)', '1989', 'Action', 'Sega', '1', 'Military', 'Top-down run and gun shooter.', 'Rescue hostages and defeat the enemy army.', 'European version of the classic Rambo-style shooter.', 'Secret Command offers intense overhead action. Use your machine gun and explosive arrows to clear enemy bases and rescue captives in this quintessential 8-bit military shooter (rebranded from Rambo).');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sega-chess-europe', 'Master System', 'Sega Chess (Europe)', '1991', 'Board', 'Sega', '2', 'Chess', 'Board game simulation.', 'Defeat the computer or a friend in Chess.', 'A sophisticated 8-bit chess engine.', 'Sega Chess features a surprisingly deep AI with multiple difficulty levels. Perfect your opening moves and endgame strategy in this clean and functional digital version of the world''s most famous strategy game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sega-world-tournament-golf-europe', 'Master System', 'Sega World Tournament Golf (Europe)', '1993', 'Sports', 'Sega', '4', 'Golf', 'Sports simulation (Golf).', 'Win the world tournament with the lowest score.', 'A comprehensive and polished golf simulation.', 'Sega World Tournament Golf offers multiple courses and professional mechanics. Master the power bar and account for wind and terrain in this deeply rewarding 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('seishun-scandal-japan', 'Master System', 'Seishun Scandal (Japan)', '1986', 'Adventure', 'Sega', '1', 'Drama', 'Side-scrolling beat ''em up.', 'Fight through the city to rescue your girlfriend.', 'The original Japanese version of My Hero.', 'Seishun Scandal is a high-energy brawler with a quirky art style. Punch and kick your way through relentless waves of thugs and save the day in this challenging early Sega arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sensible-soccer-europe', 'Master System', 'Sensible Soccer (Europe)', '1992', 'Sports', 'Sensible Software', '2', 'Simulation', 'Top-down sports simulation.', 'Score more goals than your opponent.', 'A fast-paced, zoomed-out tactical soccer game.', 'Sensible Soccer on the Master System brings the legendary "Sensi" gameplay home. Master the precise passing and curling shots in this highly addictive and responsive 8-bit football simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-dancer-europe', 'Master System', 'Shadow Dancer (Europe)', '1989', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Defuse bombs and defeat the Union Lizard cult.', 'A ninja action game featuring a loyal attack dog.', 'Shadow Dancer is a unique entry in the Shinobi series. Use your canine companion to pin down enemies while you strike with shurikens in this stylish and challenging 8-bit arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shadow-of-the-beast-europe', 'Master System', 'Shadow of the Beast (Europe)', '1989', 'Action', 'Reflections Interactive', '1', 'Fantasy', 'Side-scrolling action adventure.', 'Revenge your family and regain your human form.', 'A dark, atmospheric masterpiece with stunning art.', 'Shadow of the Beast is a technical marvel. Featuring multi-layered parallax scrolling and a haunting soundtrack, navigate a surreal world filled with grotesque monsters in this legendary computer port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shanghai-usa-europe', 'Master System', 'Shanghai (USA, Europe)', '1988', 'Puzzle', 'Activision', '2', 'Board', 'Tile-matching puzzle.', 'Clear the board by matching pairs of tiles.', 'A relaxing and strategic 8-bit Mahjong game.', 'Shanghai brings the ancient Chinese puzzle to the Master System. Test your observation skills and strategy as you carefully remove tiles from a massive stack in this timeless logic classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinobi-japan', 'Master System', 'Shinobi (Japan)', '1987', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Rescue the kidnapped ninja children from Zeed.', 'The foundational Japanese ninja masterpiece.', 'Shinobi is a pillar of the Sega library. Master the art of the shuriken and close-quarters combat as you infiltrate enemy bases and face off against iconic bosses like Kasumi and Black Turtle.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shinobi-usa-europe', 'Master System', 'Shinobi (USA, Europe)', '1987', 'Action', 'Sega', '1', 'Ninja', 'Side-scrolling action platformer.', 'Rescue the kidnapped ninja children from Zeed.', 'The international release of the legendary ninja game.', 'Experience the challenge of Shinobi on the Master System. Featuring tight controls and varied magic attacks, this version remains a fan favorite for its precise platforming and intense boss battles.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('shooting-gallery-usa-europe', 'Master System', 'Shooting Gallery (USA, Europe)', '1989', 'Shooter', 'Sega', '1', 'Shooting', 'Light phaser shooting gallery.', 'Hit the moving targets and avoid the obstacles.', 'A variety-packed target shooter for the Light Phaser.', 'Shooting Gallery offers multiple themed levels, from balloons to pipes. Test your reflexes and accuracy in this competitive arcade-style game designed specifically for the Sega light gun.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silver-sonic-the-crystal-islands-easy-mode', 'Master System', 'Silver Sonic The Crystal Islands Easy Mode', '2023', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Collect Chaos Emeralds and defeat Robotnik easily.', 'An accessible fan-made Sonic adventure.', 'Silver Sonic The Crystal Islands Easy Mode offers a relaxed way to enjoy this creative hack. Featuring custom levels and music, it''s perfect for players who want to explore without the high difficulty.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silver-sonic-the-crystal-islands-hard-mode', 'Master System', 'Silver Sonic The Crystal Islands Hard Mode', '2023', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Collect Chaos Emeralds and defeat Robotnik.', 'A punishingly difficult fan-made Sonic challenge.', 'Silver Sonic The Crystal Islands Hard Mode tests the limits of any Sonic fan. Navigate complex, trap-filled custom levels that require frame-perfect jumping and expert timing to survive.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('silver-sonic-the-crystal-islands-refreshed', 'Master System', 'Silver Sonic The Crystal Islands Refreshed', '2023', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Collect Chaos Emeralds and defeat Robotnik.', 'A polished and updated version of the Silver Sonic hack.', 'This Refreshed version of Silver Sonic The Crystal Islands brings improved level design and bug fixes to the fan project. Experience a fresh take on 8-bit Sonic with unique visuals and mechanics.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---bart-vs-the-space-mutants-europe', 'Master System', 'Simpsons, The - Bart vs. The Space Mutants (Europe)', '1991', 'Platform', 'Imagitec Design', '1', 'Cartoon', 'Side-scrolling action adventure.', 'Stop the aliens from turning objects purple.', 'A creative Simpsons quest through Springfield.', 'Bart vs. the Space Mutants is a unique blend of platforming and puzzle-solving. Use X-ray glasses and spray paint to thwart the alien invasion in this colorful and difficult movie tie-in.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('simpsons-the---bart-vs-the-world-europe', 'Master System', 'Simpsons, The - Bart vs. The World (Europe)', '1992', 'Platform', 'Imagitec Design', '1', 'Cartoon', 'Side-scrolling platformer.', 'Compete in various world challenges to win.', 'A globe-trotting Simpsons adventure.', 'Bart vs. the World takes the Simpson family to China, Egypt, and beyond. Complete diverse mini-games and platforming stages to defeat the Krustylu empire in this vibrant 8-bit sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sitio-do-picapau-amarelo-brazil', 'Master System', 'Sitio do Picapau Amarelo (Brazil)', '1997', 'Educational', 'Tectoy', '1', 'Cartoon', 'Side-scrolling platformer.', 'Solve the mysteries of the magical farm.', 'A Brazilian exclusive based on the famous literature.', 'Sítio do Picapau Amarelo is a rare Tectoy masterpiece. Play as Pedrinho or Emília and explore the magical world created by Monteiro Lobato in this polished and colorful 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slap-shot-europe', 'Master System', 'Slap Shot (Europe)', '1990', 'Sports', 'Taito', '2', 'Hockey', 'Sports simulation (Hockey).', 'Win the championship through aggressive play.', 'A fast and physical 8-bit ice hockey game.', 'Slap Shot features high-speed skating and the ability to engage in fights. Lead your team to victory with strategic passing and powerful shots in this competitive European sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slap-shot-usa', 'Master System', 'Slap Shot (USA)', '1990', 'Sports', 'Taito', '2', 'Hockey', 'Sports simulation (Hockey).', 'Win the championship through aggressive play.', 'The North American release of the hockey sim.', 'Experience the intensity of the rink in Slap Shot. This US version offers smooth animation and responsive controls, making it one of the most playable hockey games on 8-bit hardware.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('slap-shot-usa-v11', 'Master System', 'Slap Shot (USA) (v1.1)', '1990', 'Sports', 'Taito', '2', 'Hockey', 'Sports simulation (Hockey).', 'Win the championship through aggressive play.', 'Updated version of the North American hockey hit.', 'Slap Shot v1.1 provides refined mechanics and minor bug fixes. Master the ice and outplay your rivals in this definitive version of Sega’s aggressive hockey simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('smurfs-the-europe-enfrdees', 'Master System', 'Smurfs, The (Europe) (En,Fr,De,Es)', '1994', 'Platform', 'Infogrames', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save your fellow Smurfs from Gargamel.', 'A beautiful and faithful Smurfs adventure.', 'The Smurfs features incredible graphics that capture the look of the cartoon. Navigate through the forest and the village, avoiding traps and enemies in this polished late-generation platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('solomon-no-kagi---oujo-rihita-no-namida-japan', 'Master System', 'Solomon no Kagi - Oujo Rihita no Namida (Japan)', '1988', 'Puzzle', 'Tecmo', '1', 'Fantasy', 'Puzzle-solving action.', 'Collect keys to open doors and escape each room.', 'A strategic Japanese puzzle game with magic.', 'Solomon no Kagi (Solomon''s Key) tasks you with creating and destroying blocks to navigate levels. Use your magic and logic to solve increasingly difficult rooms in this clever 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-2-remastered', 'Master System', 'Sonic 2 ReMastered', '2022', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Stop Dr. Eggman and rescue your friends.', 'A technical overhaul of the classic Sonic 2.', 'Sonic 2 ReMastered features improved color palettes, fixed physics, and restored content. It is the ultimate fan-made way to experience the legendary 8-bit Sonic sequel on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-blast-brazil', 'Master System', 'Sonic Blast (Brazil)', '1996', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Collect Chaos Emeralds in a high-speed adventure.', 'A rare 8-bit port of the Game Gear original.', 'Sonic Blast (Brazil) features large, pre-rendered sprites that push the Master System''s limits. Play as Sonic or Knuckles and race through vibrant zones in this late-era Sega collectible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-chaos-europe', 'Master System', 'Sonic Chaos (Europe)', '1993', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Stop Dr. Robotnik from stealing the Chaos Emeralds.', 'A fast-paced adventure with multiple playable characters.', 'Sonic Chaos features the debut of Tails as a playable character on the system. Use Sonic’s speed or Tails’ flight to explore creative zones and recover the emeralds in this polished sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-eclipse-demo', 'Master System', 'Sonic Eclipse Demo', '2021', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Explore the demo levels to test new features.', 'A technical demo for a fan-made Sonic project.', 'Sonic Eclipse Demo showcases new 8-bit Sonic mechanics and visual styles. It serves as a proof-of-concept for modern developers working with the Sega Master System hardware constraints.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-genesis-for-master-system', 'Master System', 'Sonic Genesis for Master System', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Complete levels using Mega Drive style mechanics.', 'A reimagining of the 16-bit Sonic for 8-bit.', 'Sonic Genesis for Master System attempts to bring the feel of the original Mega Drive game to the 8-bit console. It features modified level layouts and music to bridge the gap between the two eras.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-labyrinth', 'Master System', 'Sonic Labyrinth', '1995', 'Puzzle', 'Sega', '1', 'Abstract', 'Isometric puzzle-action.', 'Find the keys and escape the labyrinth.', 'A unique top-down perspective Sonic adventure.', 'Sonic Labyrinth is a departure from the high-speed norm. Use the Spin Dash to navigate complex mazes and solve puzzles under a time limit in this 8-bit port of the Game Gear original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-spinball-europe', 'Master System', 'Sonic Spinball (Europe)', '1993', 'Platform', 'Sega', '1', 'Arcade', 'Pinball action-adventure.', 'Collect Chaos Emeralds within pinball tables.', 'A unique mix of Sonic platforming and pinball.', 'Sonic Spinball brings the high-stakes table action to the Master System. Navigate through four massive levels, using Sonic as the ball to defeat Robotnik’s mechanical creations.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog---phantom-remix', 'Master System', 'Sonic the Hedgehog - Phantom Remix', '2022', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Experience the classic game with new visual flair.', 'A graphical and musical remix of Sonic 1.', 'Sonic the Hedgehog - Phantom Remix offers a fresh aesthetic for the first 8-bit Sonic game. Featuring custom palettes and music, it provides a "new" experience for veteran players of the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-usa-europe', 'Master System', 'Sonic The Hedgehog (USA, Europe)', '1991', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue the animals and stop Dr. Robotnik.', 'The definitive 8-bit debut of the Sega mascot.', 'Sonic the Hedgehog is a masterpiece of speed and level design. Unlike the 16-bit version, it features unique levels and a different focus on exploration, making it a must-play Master System classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-2---miles-mode', 'Master System', 'Sonic the Hedgehog 2 - Miles mode', '2020', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Complete Sonic 2 playing as Miles Prower.', 'A character-swap hack for the Sonic sequel.', 'Sonic the Hedgehog 2 - Miles Mode allows you to play through the entire game as Tails with his unique flying abilities. Discover new ways to navigate the levels and defeat bosses with this fan-made modification.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-2---tails-mode', 'Master System', 'Sonic the Hedgehog 2 - Tails mode', '2020', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Complete Sonic 2 playing as Miles Prower.', 'A character-swap hack for the Sonic sequel.', 'Sonic the Hedgehog 2 - Tails Mode (variant) provides the same flying-based gameplay as Miles Mode. Use the twin-tailed fox''s flight to bypass difficult sections and find hidden items throughout the game.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-2-europe', 'Master System', 'Sonic The Hedgehog 2 (Europe)', '1992', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Tails from the clutches of Dr. Robotnik.', 'The challenging and high-speed Sonic sequel.', 'Sonic the Hedgehog 2 on the Master System is famous for its high difficulty and unique vehicle stages, like the hang glider and minecart. It is a technical showcase of what the system can achieve.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-2-europe-v11', 'Master System', 'Sonic The Hedgehog 2 (Europe) (v1.1)', '1992', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Rescue Tails from the clutches of Dr. Robotnik.', 'Refined version of the 8-bit Sonic sequel.', 'This v1.1 of Sonic 2 features minor bug fixes and tweaks to the level balance. Experience the frantic search for the Chaos Emeralds in the most polished version of this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-challenge-mode', 'Master System', 'Sonic The Hedgehog Challenge Mode', '2021', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Survive specific high-stakes trials in Sonic 1.', 'A trial-based modification of the first Sonic game.', 'Sonic the Hedgehog Challenge Mode strips away the exploration to focus on pure platforming skill. Complete specific objectives and time trials in this fan-made competitive enhancement.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-the-hedgehog-sms---nc-revision--s1nc', 'Master System', 'Sonic the Hedgehog SMS - NC Revision / S1NC', '2021', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Experience a revised version of the 8-bit classic.', 'A technical revision of the original Sonic game.', 'Sonic the Hedgehog SMS - NC Revision (S1NC) features numerous fixes to the physics and code of the original game. It aims to provide the smoothest and most accurate 8-bit Sonic experience possible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonic-triple-trouble-sms', 'Master System', 'Sonic Triple Trouble SMS', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Collect the Chaos Emeralds and stop Nack the Weasel.', 'A Master System port of the Game Gear classic.', 'Sonic Triple Trouble SMS is a fan-made port that brings the Game Gear exclusive to the big screen. Play as Sonic or Tails, utilizing new vehicles and power-ups to defeat Dr. Robotnik and the newcomer Fang the Sniper.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sonics-edusoft', 'Master System', 'Sonic''s Edusoft', '1995', 'Educational', 'Sega', '1', 'Educational', 'Educational puzzle adventure.', 'Solve math and spelling puzzles to earn emeralds.', 'An unreleased Sonic edutainment prototype.', 'Sonic''s Edusoft features a series of educational mini-games set in the Sonic universe. Navigate a Green Hill-inspired overworld to solve logic, math, and word puzzles in this rare piece of Sega history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-gun-europe', 'Master System', 'Space Gun (Europe)', '1992', 'Shooter', 'Ocean Software', '1', 'Arcade', 'First-person rail shooter.', 'Rescue hostages and eliminate alien invaders.', 'A gritty sci-fi shooter compatible with the Light Phaser.', 'Space Gun brings Taito''s intense arcade shooter to the Master System. Navigate the corridors of a hijacked spacecraft, using a variety of weapons to blast through grotesque aliens while saving the remaining human crew.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-harrier-japan', 'Master System', 'Space Harrier (Japan)', '1985', 'Action', 'Sega', '1', 'Arcade', 'Third-person rail shooter.', 'Fly through the "Dragon Land" and defeat bosses.', 'The original Japanese version of the surreal shooter.', 'Space Harrier (Japan) is a vibrant and fast-paced arcade conversion. Use your jet-powered blaster to dodge obstacles and take down bizarre enemies in this foundational title of the rail-shooter genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-harrier-usa-europe', 'Master System', 'Space Harrier (USA, Europe)', '1985', 'Action', 'Sega', '1', 'Arcade', 'Third-person rail shooter.', 'Fly through the "Dragon Land" and defeat bosses.', 'The international release of the iconic fantasy shooter.', 'Experience the speed of Space Harrier. Battle through 18 stages of surreal landscapes and massive dragons in this technically impressive 8-bit port that captures the high-energy spirit of the arcade original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-harrier-3-d-usa-europe', 'Master System', 'Space Harrier 3-D (USA, Europe)', '1988', 'Action', 'Sega', '1', 'Arcade', 'Third-person 3D rail shooter.', 'Fly through the "Dragon Land" using 3D depth.', 'A stereoscopic version designed for 3D Glasses.', 'Space Harrier 3-D uses Sega''s 3D technology to add an incredible sense of scale to the "Fantasy Zone." Dodge incoming fire and navigate pillars in a fully immersive 8-bit 3D environment.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('space-harrier-3d-japan', 'Master System', 'Space Harrier 3D (Japan)', '1988', 'Action', 'Sega', '1', 'Arcade', 'Third-person 3D rail shooter.', 'Fly through the "Dragon Land" using 3D depth.', 'The Japanese 3D edition of the fantasy shooter.', 'Master the skies in Space Harrier 3D (Japan). This version utilizes the Master System''s 3D Glasses to bring the arcade''s pseudo-3D effects to life, offering a unique and challenging perspective on the classic gameplay.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('special-criminal-investigation-europe', 'Master System', 'Special Criminal Investigation (Europe)', '1989', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back combat racing.', 'Chase down criminals and stop them within the time limit.', 'The high-octane sequel to the hit Chase H.Q.', 'Special Criminal Investigation (S.C.I.) adds weapon combat to the pursuit formula. Drive your pursuit vehicle at breakneck speeds, shooting and ramming criminals to bring them to justice before time runs out.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('special-criminal-investigation-europe-beta', 'Master System', 'Special Criminal Investigation (Europe) (Beta)', '1989', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back combat racing.', 'Chase down criminals and stop them within the limit.', 'Beta version of the fast-paced pursuit sequel.', 'This Beta build of S.C.I. allows players to experience the early development of the combat-racing mechanics. Test your driving skills and firepower in this rare look at the European pursuit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedball-europe-mirrorsoft', 'Master System', 'Speedball (Europe) (Mirrorsoft)', '1988', 'Sports', 'Mirrorsoft', '2', 'Arcade', 'Top-down sports action.', 'Score more goals than the rival team in a brutal arena.', 'A violent futuristic take on handball.', 'Speedball (Mirrorsoft) is a fast and gritty sports simulation. Use speed, strategy, and sheer force to outplay your opponents in a steel-enclosed arena where there are almost no rules except victory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedball-europe-virgin', 'Master System', 'Speedball (Europe) (Virgin)', '1988', 'Sports', 'Virgin Interactive', '2', 'Arcade', 'Top-down sports action.', 'Score more goals than the rival team in a brutal arena.', 'The Virgin Games edition of the futuristic sports hit.', 'Speedball features high-speed metallic ball physics and intense physical contact. Master the power-ups and tactical maneuvers to climb the league rankings in this definitive 8-bit port of the computer classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('speedball-2-europe', 'Master System', 'Speedball 2 (Europe)', '1991', 'Sports', 'Image Works', '2', 'Arcade', 'Top-down sports action.', 'Win the league and upgrade your futuristic team.', 'The acclaimed sequel with deeper team management.', 'Speedball 2: Brutal Deluxe expands on the original with more arenas, better graphics, and the ability to upgrade your players. It is the ultimate version of the "sport of the future" on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spellcaster-usa-europe', 'Master System', 'SpellCaster (USA, Europe)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action adventure.', 'Use magical spells to defeat the dark gods.', 'A deep blend of platforming and menu-driven adventure.', 'SpellCaster features a unique mix of combat and storytelling. Play as Kane, using a variety of elemental spells to battle monsters and solve environmental puzzles in this epic journey through ancient Japan.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man---return-of-the-sinister-six-europe', 'Master System', 'Spider-Man - Return of the Sinister Six (Europe)', '1992', 'Action', 'Imagineering', '1', 'Superhero', 'Side-scrolling action platformer.', 'Defeat the Sinister Six and save the city.', 'A challenging superhero quest based on the comics.', 'Spider-Man: Return of the Sinister Six tasks you with defeating Spidey''s greatest foes. Use your web-shooters and wall-crawling abilities to navigate trap-filled levels in this late-gen 8-bit action title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spider-man-vs-the-kingpin-usa-europe', 'Master System', 'Spider-Man vs. The Kingpin (USA, Europe)', '1991', 'Action', 'Teeny Weeny Games', '1', 'Superhero', 'Side-scrolling action platformer.', 'Stop the Kingpin’s bomb and clear your name.', 'A cinematic and high-stakes Spider-Man adventure.', 'Spider-Man vs. The Kingpin features iconic villains and non-linear exploration. Race against the clock to collect the keys needed to disarm a nuclear bomb in this visually impressive and difficult classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spin-dash-in-sonic-2-sms', 'Master System', 'Spin Dash in Sonic 2 SMS', '2021', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Complete Sonic 2 using the Spin Dash mechanic.', 'A gameplay-enhancing modification of Sonic 2.', 'Spin Dash in Sonic 2 SMS adds the iconic charge-up move to the 8-bit sequel. This fan-made tweak modernizes the gameplay, allowing for better momentum and a fresh way to tackle the game''s difficult zones.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-pad-football-usa', 'Master System', 'Sports Pad Football (USA)', '1989', 'Sports', 'Sega', '2', 'Football', 'Sports simulation (Football).', 'Score touchdowns using the Sports Pad controller.', 'An American football game designed for the trackball.', 'Sports Pad Football utilizes the specialized Master System trackball for more precise movement and play-calling. Lead your team to victory on the gridiron in this unique hardware-focused sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sports-pad-soccer-japan', 'Master System', 'Sports Pad Soccer (Japan)', '1989', 'Sports', 'Sega', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the match using the Sports Pad controller.', 'A Japanese soccer game designed for the trackball.', 'Sports Pad Soccer offers a unique control scheme for the world''s most popular sport. Use the trackball to aim shots and control player movement in this innovative and rare Japanese sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spy-vs-spy-japan', 'Master System', 'Spy vs Spy (Japan)', '1984', 'Strategy', 'Sega', '2', 'Board', 'Top-down strategy action.', 'Find all items and trap your rival in the embassy.', 'The Japanese version of the classic MAD Magazine game.', 'Spy vs Spy (Japan) is a brilliant game of traps and sabotage. Outsmart your rival spy in a split-screen race to find the secret documents and escape before the building explodes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('spy-vs-spy-usa-europe', 'Master System', 'Spy vs. Spy (USA, Europe)', '1984', 'Strategy', 'Sega', '2', 'Board', 'Top-down strategy action.', 'Find all items and trap your rival in the embassy.', 'The international release of the trap-setting classic.', 'Master the art of the booby-trap in Spy vs. Spy. This 8-bit port captures the dark humor of the comics, requiring players to search furniture and set deadly traps to hinder their opponent''s progress.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('star-wars-europe', 'Master System', 'Star Wars (Europe)', '1993', 'Action', 'U.S. Gold', '1', 'Movie', 'Side-scrolling action platformer.', 'Destroy the Death Star and defeat the Empire.', 'An epic 8-bit adaptation of the legendary film.', 'Star Wars on the Master System is a massive adventure spanning Tatooine to the Death Star. Play as Luke Skywalker, Han Solo, or Leia as you battle Stormtroopers and pilot the X-Wing in this cinematic classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('street-fighter-ii-brazil', 'Master System', 'Street Fighter II (Brazil)', '1994', 'Fighting', 'Capcom', '2', 'Arcade', 'One-on-one fighting game.', 'Defeat the world warriors to become the champion.', 'A rare and officially licensed 8-bit port from Brazil.', 'Street Fighter II (Brazil) is a technical wonder. Despite the 8-bit hardware, it features a roster of 8 iconic fighters and large sprites, offering a unique and localized version of the world''s most famous fighter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('streets-of-rage-europe', 'Master System', 'Streets of Rage (Europe)', '1991', 'Beat ''em up', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Clean up the streets and defeat Mr. X.', 'The legendary urban brawler comes to 8-bit.', 'Streets of Rage brings the hard-hitting action of the Mega Drive original to the Master System. Choose from Axel, Blaze, or Adam and use devastating special moves to take back the city from the criminal syndicate.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('streets-of-rage-ii-europe', 'Master System', 'Streets of Rage II (Europe)', '1993', 'Beat ''em up', 'Sega', '2', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue Adam and defeat the mysterious Mr. X.', 'A visually impressive sequel to the urban brawler.', 'Streets of Rage II features larger sprites and improved combat mechanics. Battle through diverse urban environments and face off against tough bosses in this high-quality late-release action masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strider-usa-europe', 'Master System', 'Strider (USA, Europe)', '1992', 'Action', 'Capcom', '1', 'Arcade', 'Side-scrolling action platformer.', 'Infiltrate the Kazakh Soviet Socialist Republic.', 'A fast-paced arcade port with fluid movement.', 'Strider puts you in the role of the master assassin Hiryu. Use your "Cypher" blade and impressive climbing abilities to navigate through massive, futuristic levels in this challenging 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strider-ii-europe', 'Master System', 'Strider II (Europe)', '1994', 'Action', 'Capcom', '1', 'Arcade', 'Side-scrolling action platformer.', 'Rescue the Grandmaster and defeat the new threats.', 'The 8-bit sequel to the legendary ninja-assassin hit.', 'Strider II features even faster gameplay and more complex level design. Armed with your plasma sword, traverse through high-tech environments and engage in intense boss battles in this polished action sequel.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('strike-dash-in-sonic-2-sms', 'Master System', 'Strike Dash in Sonic 2 SMS', '2021', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Use the Strike Dash to gain speed in Sonic 2.', 'A speed-focused modification of the Sonic sequel.', 'Strike Dash in Sonic 2 SMS adds a powerful burst of speed to Sonic''s arsenal. This fan-made revision allows players to blast through enemies and obstacles, changing the flow of the classic 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('submarine-attack-europe', 'Master System', 'Submarine Attack (Europe)', '1990', 'Shooter', 'Sims', '1', 'Arcade', 'Side-scrolling submarine shooter.', 'Destroy the enemy fleet and their secret bases.', 'A unique and atmospheric underwater shmup.', 'Submarine Attack features smooth scrolling and a variety of weapon upgrades. Navigate treacherous underwater caverns and face massive mechanical sea monsters in this polished and original 8-bit shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('sukeban-deka-ii---shoujo-tekkamen-densetsu-japan', 'Master System', 'Sukeban Deka II - Shoujo Tekkamen Densetsu (Japan)', '1986', 'Action', 'Sega', '1', 'Drama', 'Multi-genre action adventure.', 'Use your yo-yo to fight crime and solve the mystery.', 'A Japanese hybrid based on the cult-hit media.', 'Sukeban Deka II features a mix of first-person exploration, text-adventure menus, and side-scrolling combat. Play as the iron-masked detective Saki, using her metal yo-yo to take down high-school gangs.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('summer-games-europe', 'Master System', 'Summer Games (Europe)', '1988', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Win the gold medal across various athletic events.', 'A classic Epyx sports compilation for the 8-bit era.', 'Summer Games features events like hurdles, swimming, and gymnastics. Test your timing and reflexes in this competitive sports title that allows multiple players to go head-to-head for Olympic glory.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('summer-games-europe-beta', 'Master System', 'Summer Games (Europe) (Beta)', '1988', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Win the gold medal across various athletic events.', 'Beta version of the multi-sport athletic challenge.', 'This Beta version of Summer Games offers an early look at the 8-bit athletic events. Practice your timing and master the controls of each discipline in this rare build of the classic sports anthology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-boy-1-unl', 'Master System', 'Super Boy 1 (Unl)', '1993', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Reach the end of the level and rescue the princess.', 'An unlicensed Korean clone of the original Super Mario Bros.', 'Super Boy 1 is a rare piece of Korean gaming history. It adapts the classic Mario gameplay for the Master System hardware, offering a unique—if unofficial—take on the platforming genre.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-boy-2-unl', 'Master System', 'Super Boy 2 (Unl)', '1993', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate through dangerous levels to save the world.', 'An unlicensed sequel based on Mario and Wonder Boy.', 'Super Boy 2 continues the unlicensed Korean saga, featuring improved graphics and levels that borrow heavily from famous platforming hits, creating a curious hybrid for 8-bit collectors.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-boy-3-unl', 'Master System', 'Super Boy 3 (Unl)', '1993', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Use power-ups to clear stages and defeat bosses.', 'A Korean unlicensed platformer with more original art.', 'Super Boy 3 evolves the series with more distinct sprites and level designs. It remains a fascinating look at the "gray market" of Korean software during the Master System''s peak popularity.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-boy-4-unl', 'Master System', 'Super Boy 4 (Unl)', '1993', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat enemies and find secrets across several worlds.', 'The final entry in the unlicensed Korean Super Boy series.', 'Super Boy 4 offers the most refined gameplay of the series. Often found on multi-game cartridges, it represents the peak of unlicensed 8-bit platforming development in Korea.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-kick-off-europe-enfrdeesitnlptsv', 'Master System', 'Super Kick Off (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1991', 'Sports', 'Anco', '2', 'Soccer', 'Top-down sports simulation.', 'Win the league with fast-paced, tactical soccer.', 'An enhanced, faster version of the classic Kick Off.', 'Super Kick Off is widely regarded as one of the best 8-bit soccer games. Its focus on ball control and high-speed passing provides a steep learning curve and a deeply rewarding competitive experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-mario-world---super-boy-4', 'Master System', 'Super Mario World - Super Boy 4', '1993', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Finish levels using Mario-inspired sprites.', 'A fan-made hack merging Super Boy 4 and Mario.', 'Super Mario World - Super Boy 4 is a community modification that skins the unlicensed Korean game with Super Mario assets, creating a fun "what if" scenario for Master System players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-monaco-gp-europe', 'Master System', 'Super Monaco GP (Europe)', '1989', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Win the Monaco Grand Prix and the world title.', 'A high-speed, technical Formula One simulator.', 'Super Monaco GP brings the intensity of arcade racing to your living room. Featuring a deep career mode and realistic handling, it is the definitive 8-bit F1 experience for racing fans.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-monaco-gp-usa', 'Master System', 'Super Monaco GP (USA)', '1989', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Win the Monaco Grand Prix and the world title.', 'North American release of the hit F1 racer.', 'Master the tight corners of the Monaco circuit in this US version. This port is known for its impressive scaling graphics and the tension of competing against professional AI drivers.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-off-road-europe', 'Master System', 'Super Off Road (Europe)', '1989', 'Racing', 'Leland', '2', 'Arcade', 'Isometric off-road racing.', 'Win races and earn money for truck upgrades.', 'A gritty and addictive dirt-track racing port.', 'Super Off Road features Ivan "Ironman" Stewart’s high-octane racing. Upgrade your shocks, nitro, and engine to outmaneuver rivals on bumpy, obstacle-filled tracks in this classic 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-racing-japan', 'Master System', 'Super Racing (Japan)', '1988', 'Racing', 'Sega', '1', 'Arcade', 'Top-down racing simulation.', 'Master the track and set the record time.', 'A Japanese exclusive racing game with car tuning.', 'Super Racing focuses on precision and vehicle maintenance. Choose your tires and gear ratios carefully to shave seconds off your lap time in this technical and rewarding 8-bit racer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-smash-tv-europe', 'Master System', 'Super Smash T.V. (Europe)', '1991', 'Action', 'Beam Software', '2', 'Arcade', 'Top-down arena shooter.', 'Survive the game show and win big prizes.', 'A frantic, multi-directional "run and gun" arcade port.', 'Super Smash T.V. is total chaos. Battle through rooms filled with hundreds of enemies and massive bosses in a futuristic game show where "Big Money" and "Big Prizes" are the only goals.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-space-invaders-europe', 'Master System', 'Super Space Invaders (Europe)', '1991', 'Shooter', 'Taito', '1', 'Arcade', 'Fixed-screen shooter.', 'Destroy the invading aliens and their motherships.', 'A modernized and vibrant take on the arcade legend.', 'Super Space Invaders adds power-ups and varied boss battles to the classic formula. Experience 8-bit shooting with improved colors and faster gameplay while defending Earth from the alien swarm.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-tennis-usa-europe', 'Master System', 'Super Tennis (USA, Europe)', '1984', 'Sports', 'Sega', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the Grand Slam and become world number one.', 'A colorful and highly playable tennis game.', 'Super Tennis offers a variety of courts and shot types. Master the serve and volley to defeat international opponents in this responsive and charming 8-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-wonder-boy---monster-world-japan', 'Master System', 'Super Wonder Boy - Monster World (Japan)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action platformer.', 'Save the kingdom by collecting gear and defeating bosses.', 'The Japanese version of Wonder Boy in Monster Land.', 'Super Wonder Boy: Monster World is a legendary blend of platforming and light RPG elements. Buy swords and armor to survive a world filled with mythical creatures and secret treasures.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('super-wonder-boy-japan', 'Master System', 'Super Wonder Boy (Japan)', '1986', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling platformer.', 'Reach the end of the level before the timer expires.', 'The Japanese version of the original Wonder Boy.', 'Super Wonder Boy is a masterclass in momentum-based platforming. Ride skateboards and throw hatchets as you race through islands and forests in this vibrant Sega arcade classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('superman---the-man-of-steel-europe', 'Master System', 'Superman - The Man of Steel (Europe)', '1993', 'Action', 'Tynesoft', '1', 'Superhero', 'Side-scrolling action platformer.', 'Save Metropolis and stop Brainiac and Lex Luthor.', 'A cinematic superhero brawler with flying stages.', 'Superman: The Man of Steel features impressive graphics and varied gameplay. Switch between ground combat and high-flying aerial shooting as you use Superman''s powers to protect the city.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('t2---the-arcade-game-europe', 'Master System', 'T2 - The Arcade Game (Europe)', '1991', 'Action', 'Probe Software', '1', 'Movie', 'First-person light gun shooter.', 'Protect John and Sarah Connor from the T-1000.', 'A high-stakes shooting gallery based on the movie.', 'T2: The Arcade Game is a relentless battle against Skynet. Compatible with the Light Phaser, blast through waves of Terminators and hunter-killers in this cinematic and action-packed 8-bit conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tails-in-sonic-the-hedgehog', 'Master System', 'Tails in Sonic The Hedgehog', '2021', 'Platform', 'Fan Made', '1', 'Cartoon', 'Side-scrolling platformer (Hack).', 'Play through Sonic 1 as the twin-tailed fox.', 'A character-swap hack of the first Sonic game.', 'Tails in Sonic the Hedgehog allows you to fly through the zones of South Island. Use Tails’ unique abilities to find new shortcuts and secrets in this fresh take on the 8-bit original.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taito-chase-hq-europe', 'Master System', 'Taito Chase H.Q. (Europe)', '1989', 'Racing', 'Taito', '1', 'Arcade', 'Behind-the-back combat racing.', 'Catch the criminals and ram them into submission.', 'A high-tension police pursuit arcade port.', 'Taito Chase H.Q. puts you behind the wheel of a black Porsche. Race through city streets to find the target and use your turbo boosts to ram them off the road before time expires.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-in-escape-from-mars-brazil', 'Master System', 'Taz in Escape from Mars (Brazil)', '1994', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Escape from a Martian zoo and return to Earth.', 'A zany and colorful Looney Tunes adventure.', 'Taz in Escape from Mars features the chaotic energy of the Tasmanian Devil. Spin through Martian labs and gladiatorial arenas in this visually impressive and difficult late-era platformer.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania-europe', 'Master System', 'Taz-Mania (Europe)', '1992', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the giant seabird egg for a massive feast.', 'A high-speed Looney Tunes chase game.', 'Taz-Mania features the iconic spinning move of Taz. Navigate through dangerous cliffs and deserts, eating items and avoiding traps in this vibrant and charming 8-bit adaptation of the cartoon.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('taz-mania-europe-beta', 'Master System', 'Taz-Mania (Europe) (Beta)', '1992', 'Platform', 'Sega', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the giant seabird egg for a massive feast.', 'Beta version of the Tasmanian Devil adventure.', 'This Beta version of Taz-Mania offers an early look at the game''s mechanics and level design. Experience the chaotic spinning action with slight variations from the final European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-world-cup-92-europe-beta', 'Master System', 'Tecmo World Cup ''92 (Europe) (Beta)', '1992', 'Sports', 'Tecmo', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the world championship with your team.', 'Beta version of the fast-paced 1992 football sim.', 'Tecmo World Cup ''92 (Beta) allows players to test the fluid soccer mechanics of the Tecmo series. Master the timing of headers and sliding tackles in this rare piece of 8-bit sports software.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tecmo-world-cup-93-europe', 'Master System', 'Tecmo World Cup ''93 (Europe)', '1993', 'Sports', 'Tecmo', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the world championship with your team.', 'The definitive 8-bit edition of Tecmo''s soccer hit.', 'Tecmo World Cup ''93 features international teams and a smooth, arcade-style soccer experience. With its fast gameplay and simple controls, it’s one of the most accessible sports titles on the system.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teddy-boy-usa-europe', 'Master System', 'Teddy Boy (USA, Europe)', '1985', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling arcade action.', 'Clear each room of monsters and collect the balls.', 'A fast-paced and quirky early Sega classic.', 'Teddy Boy features non-stop shooting and platforming. Navigate through complex, wrap-around rooms to shrink enemies and collect them, all while racing against the clock in this addictive arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teddy-boy-blues-japan', 'Master System', 'Teddy Boy Blues (Japan)', '1985', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling arcade action.', 'Clear each room of monsters and collect the balls.', 'The original Japanese version of Teddy Boy.', 'Teddy Boy Blues (Japan) features the same frantic gameplay with a catchy J-pop soundtrack. It’s an early showcase for the Master System’s ability to handle fast, flickering-free arcade action.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('teddy-boy-blues-japan-proto-ep-mycard', 'Master System', 'Teddy Boy Blues (Japan) (Proto) (Ep-MyCard)', '1985', 'Action', 'Sega', '1', 'Arcade', 'Side-scrolling arcade action.', 'Clear each room of monsters and collect the balls.', 'Rare prototype of the Japanese arcade classic.', 'This prototype of Teddy Boy Blues offers a glimpse into the game''s early development. Experience the core "shrink-and-collect" mechanics in their most primitive 8-bit form.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tennis-ace-europe', 'Master System', 'Tennis Ace (Europe)', '1990', 'Sports', 'Sega', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the tournament on grass, clay, or hard court.', 'A detailed and professional tennis simulation.', 'Tennis Ace offers a realistic take on the sport. Choose your character and master the timing of power shots and lobs to defeat tough AI opponents in this polished and competitive 8-bit sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tensai-bakabon-japan', 'Master System', 'Tensai Bakabon (Japan)', '1988', 'Action', 'Sega', '1', 'Comedy', 'Point-and-click adventure.', 'Solve family puzzles and navigate the neighborhood.', 'A Japanese exclusive adventure based on the manga.', 'Tensai Bakabon is a charming and humorous title. Help the "Geniuses" through various daily tasks and puzzles in this visually distinct game that captures the spirit of the iconic Japanese comic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-2---judgment-day-europe', 'Master System', 'Terminator 2 - Judgment Day (Europe)', '1991', 'Action', 'Ocean Software', '1', 'Movie', 'Side-scrolling action platformer.', 'Protect John Connor and defeat the T-1000.', 'A cinematic action game based on the movie sequel.', 'Terminator 2: Judgment Day features a mix of combat and vehicle-based levels. Follow the plot of the blockbuster film as the protector T-800 in this dark and atmospheric 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-brazil', 'Master System', 'Terminator, The (Brazil)', '1992', 'Action', 'Sega', '1', 'Movie', 'Side-scrolling action platformer.', 'Destroy Skynet and protect Sarah Connor.', 'The Brazilian release of the gritty sci-fi shooter.', 'The Terminator (Brazil) delivers a dark, atmospheric 8-bit experience. Fight through the post-apocalyptic future and 1980s Los Angeles in this challenging action title known for its high-quality sprites and cinematic soundtrack.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('terminator-the-europe', 'Master System', 'Terminator, The (Europe)', '1992', 'Action', 'Sega', '1', 'Movie', 'Side-scrolling action platformer.', 'Destroy Skynet and protect Sarah Connor.', 'A high-stakes action game based on the original film.', 'Experience the hunt in The Terminator. As Kyle Reese, you must navigate dangerous urban environments to protect the future of humanity from an unstoppable killing machine in this polished European release.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-blade-japan', 'Master System', 'Thunder Blade (Japan)', '1987', 'Action', 'Sega', '1', 'Arcade', 'Top-down & behind-the-back shooter.', 'Destroy enemy bases and the giant fortress.', 'The Japanese version of the aerial combat hit.', 'Thunder Blade (Japan) combines overhead and pseudo-3D flight perspectives. Pilot your attack helicopter through city skyscrapers and mountain ranges to dismantle a rogue military force in this fast-paced arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('thunder-blade-usa-europe', 'Master System', 'Thunder Blade (USA, Europe)', '1987', 'Action', 'Sega', '1', 'Arcade', 'Top-down & behind-the-back shooter.', 'Destroy enemy bases and the giant fortress.', 'A high-octane helicopter combat simulation.', 'Thunder Blade for the Master System offers intense multi-perspective shooting. Master the controls of your gunship to weave through enemy fire and take down massive bosses in this technically ambitious 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('time-soldiers-usa-europe', 'Master System', 'Time Soldiers (USA, Europe)', '1989', 'Action', 'Sega', '2', 'Arcade', 'Top-down run and gun shooter.', 'Travel through time to rescue your comrades.', 'A chronological battle through human history.', 'Time Soldiers features a unique "time travel" mechanic. Fight through the Primitive Age, the Roman Era, and the World Wars to find your lost teammates in this colorful and creative overhead shooter.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-&-jerry-europe-beta', 'Master System', 'Tom & Jerry (Europe) (Beta)', '1991', 'Platform', 'Audiogenic', '1', 'Cartoon', 'Side-scrolling platformer.', 'Navigate household levels while avoiding traps.', 'Beta version of the cat-and-mouse adventure.', 'This Beta build of Tom & Jerry offers an early look at the platforming mechanics. Help Jerry navigate oversized rooms and outsmart Tom in this rare look at the game''s development process.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tom-and-jerry---the-movie-europe', 'Master System', 'Tom and Jerry - The Movie (Europe)', '1992', 'Platform', 'Spidersoft', '1', 'Cartoon', 'Side-scrolling platformer.', 'Find the lost treasure and reach the movie set.', 'A vibrant platformer based on the feature film.', 'Tom and Jerry: The Movie features high-quality animation and challenging level design. Play as Jerry in a quest that spans gardens, houses, and the city in this polished late-generation classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('toto-world-3-korea-unl', 'Master System', 'Toto World 3 (Korea) (Unl)', '1994', 'Platform', 'Unlicensed', '1', 'Cartoon', 'Side-scrolling platformer.', 'Defeat enemies and reach the goal as Toto.', 'A rare unlicensed Korean platforming gem.', 'Toto World 3 is a unique piece of Korean software history. Featuring bright colors and traditional 8-bit platforming, it follows the adventures of a charming character in a world filled with imaginative foes.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('transbot-usa-europe', 'Master System', 'TransBot (USA, Europe)', '1986', 'Shooter', 'Sega', '1', 'Arcade', 'Horizontal scrolling shoot ''em up.', 'Defeat the Daluas and their mechanical fleet.', 'A transforming mecha shooter on a card.', 'TransBot is a Master System Card-format classic. Collect power-up pods to transform your jet into different mecha forms, each with unique weaponry, to survive waves of futuristic enemies.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('trivial-pursuit---genus-edition-europe-enfrdees', 'Master System', 'Trivial Pursuit - Genus Edition (Europe) (En,Fr,De,Es)', '1984', 'Board', 'Domark', '4', 'Trivia', 'Trivia / Board game simulation.', 'Answer questions to collect wedges and win.', 'A comprehensive digital version of the board game.', 'Trivial Pursuit: Genus Edition brings the ultimate test of knowledge to the 8-bit screen. With thousands of questions across multiple categories, it’s a perfect party game for the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('turma-da-monica-em-o-resgate-brazil', 'Master System', 'Turma da Monica em O Resgate (Brazil)', '1993', 'Platform', 'Tectoy', '1', 'Cartoon', 'Side-scrolling action RPG.', 'Rescue Mônica by using different animal forms.', 'A Brazilian re-skin of Wonder Boy III.', 'Turma da Mônica em O Resgate is a legendary localized masterpiece. Based on the beloved Brazilian comic, play as various characters with unique powers to save Mônica in this deep and expansive adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('tv-colosso-brazil', 'Master System', 'TV Colosso (Brazil)', '1996', 'Platform', 'Tectoy', '1', 'Cartoon', 'Multi-game collection.', 'Complete various mini-games and challenges.', 'A Brazilian exclusive based on the TV variety show.', 'TV Colosso is a rare Tectoy title featuring the famous puppet characters from the Brazilian show. Experience a variety of fun and colorful mini-games designed for the whole family on the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-iv---quest-of-the-avatar-europe', 'Master System', 'Ultima IV - Quest of the Avatar (Europe)', '1990', 'RPG', 'Origin Systems', '1', 'Fantasy', 'Top-down open-world RPG.', 'Master the eight virtues to become the Avatar.', 'One of the deepest and most complex 8-bit RPGs.', 'Ultima IV is a landmark in role-playing history. Eschewing simple combat for a focus on morality and character, explore a massive world, interact with NPCs, and prove your virtue in this incredible port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultima-iv---quest-of-the-avatar-europe-beta', 'Master System', 'Ultima IV - Quest of the Avatar (Europe) (Beta)', '1990', 'RPG', 'Origin Systems', '1', 'Fantasy', 'Top-down open-world RPG.', 'Master the eight virtues to become the Avatar.', 'Beta version of the epic moral-based RPG.', 'Explore an early build of Britannia in the Ultima IV Beta. This version showcases the intricate systems and world-building that made the final European release a highly sought-after collectible.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('ultimate-soccer-europe-enfrdeesit', 'Master System', 'Ultimate Soccer (Europe) (En,Fr,De,Es,It)', '1993', 'Sports', 'Infogrames', '2', 'Soccer', 'Sports simulation (Soccer).', 'Win the championship using various tactics.', 'A refined and fast-paced 8-bit soccer game.', 'Ultimate Soccer offers smooth scrolling and a variety of modes, including 5-a-side and tournaments. With detailed sprites and responsive controls, it’s a standout sports title for the late-gen console.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vampire-europe-beta', 'Master System', 'Vampire (Europe) (Beta)', '1992', 'Action', 'Sanritsu Denki', '1', 'Horror', 'Side-scrolling platformer.', 'Escape the castle and defeat the monsters.', 'Beta version of an unreleased horror platformer.', 'Vampire (Beta) is a fascinating look at a project that never saw a full retail release. Navigate a haunted castle and battle ghouls in this atmospheric 8-bit action-adventure prototype.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('vigilante-usa-europe', 'Master System', 'Vigilante (USA, Europe)', '1988', 'Action', 'Irem', '1', 'Arcade', 'Side-scrolling beat ''em up.', 'Rescue your girlfriend from the Skinheads gang.', 'A gritty urban brawler with large sprites.', 'Vigilante is the spiritual successor to Kung-Fu Master. Fight your way across city streets and on top of moving trucks to rescue Madonna in this challenging and well-animated arcade conversion.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('virtua-fighter-animation-brazil', 'Master System', 'Virtua Fighter Animation (Brazil)', '1996', 'Fighting', 'Sega', '1', 'Anime', 'One-on-one fighting game.', 'Win the world tournament of martial arts.', 'An 8-bit adaptation of the 3D fighting legend.', 'Virtua Fighter Animation (Brazil) is a technical wonder based on the anime series. Featuring large sprites and fluid combat, it brings the core mechanics of the Virtua Fighter series to the Master System.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('walter-payton-football-usa', 'Master System', 'Walter Payton Football (USA)', '1989', 'Sports', 'Sega', '2', 'Football', 'Sports simulation (Football).', 'Lead your team to victory in the playoffs.', 'American football endorsed by the NFL legend.', 'Walter Payton Football delivers a strategic gridiron experience. Call the plays and execute precision passes to lead your team to the championship in this polished and competitive sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wanted-usa-europe', 'Master System', 'Wanted (USA, Europe)', '1989', 'Action', 'Sanritsu Denki', '1', 'Arcade', 'Light phaser shooting gallery.', 'Collect rewards by catching the most outlaws.', 'A Wild West shooter for the Light Phaser.', 'Wanted puts you in the boots of a frontier sheriff. Use your light gun to take down bandits while avoiding innocent civilians in this fast-paced and colorful 8-bit shooting gallery.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('where-in-the-world-is-carmen-sandiego-brazil', 'Master System', 'Where in the World is Carmen Sandiego (Brazil)', '1992', 'Educational', 'Tectoy', '1', 'Educational', 'Educational geography adventure.', 'Track down Carmen and her V.I.L.E. henchmen.', 'The Brazilian version of the mystery classic.', 'Where in the World is Carmen Sandiego? (Brazil) teaches geography through detective work. Follow clues across the globe to capture the master thief in this engaging and educational 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('where-in-the-world-is-carmen-sandiego-usa', 'Master System', 'Where in the World is Carmen Sandiego (USA)', '1992', 'Educational', 'Broderbund', '1', 'Educational', 'Educational geography adventure.', 'Track down Carmen and her V.I.L.E. henchmen.', 'A detective quest across the entire globe.', 'Become an ACME agent and track Carmen Sandiego in this classic mystery game. Use your atlas and logic to solve crimes and climb the ranks in this highly replayable educational adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wimbledon-europe', 'Master System', 'Wimbledon (Europe)', '1993', 'Sports', 'Loriciel', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the prestigious Wimbledon championship.', 'The officially licensed tournament tennis game.', 'Wimbledon features a variety of modes and professional gameplay mechanics. Master your serve and volley on the grass courts of London in this competitive and realistic 8-bit sports simulator.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wimbledon-ii-europe', 'Master System', 'Wimbledon II (Europe)', '1994', 'Sports', 'Loriciel', '2', 'Tennis', 'Sports simulation (Tennis).', 'Win the prestigious Wimbledon championship.', 'The refined sequel to the licensed tennis hit.', 'Wimbledon II offers improved graphics and tighter controls. Compete against the world''s best players and climb the rankings in this polished and challenging 8-bit tennis simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-olympics---lillehammer-94-brazil-enfrdeesitptsvno', 'Master System', 'Winter Olympics - Lillehammer ''94 (Brazil) (En,Fr,De,Es,It,Pt,Sv,No)', '1994', 'Sports', 'Tiertex', '4', 'Olympic', 'Multi-event sports simulation.', 'Win the gold medal in the 1994 Winter Games.', 'The Brazilian edition of the Olympic simulation.', 'Winter Olympics: Lillehammer ''94 features events like bobsleigh, downhill skiing, and ice hockey. Test your timing and endurance to claim the podium in this comprehensive winter sports collection.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('winter-olympics---lillehammer-94-europe-enfrdeesitptsvno', 'Master System', 'Winter Olympics - Lillehammer ''94 (Europe) (En,Fr,De,Es,It,Pt,Sv,No)', '1994', 'Sports', 'Tiertex', '4', 'Olympic', 'Multi-event sports simulation.', 'Win the gold medal in the 1994 Winter Games.', 'Official licensed game of the ''94 Winter Olympics.', 'Experience the chill of competition in Winter Olympics. With multiple athletic disciplines and realistic 8-bit physics, it offers a challenging and diverse sports experience for up to four players.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wolfchild-europe', 'Master System', 'Wolfchild (Europe)', '1992', 'Action', 'Core Design', '1', 'Sci-Fi', 'Side-scrolling action platformer.', 'Defeat the Chimera and rescue your father.', 'A dark and visually stunning action-adventure.', 'Wolfchild features a unique transformation mechanic. Collect power-ups to turn into a powerful wolf-human hybrid and battle through high-tech labs and ancient ruins in this polished 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-usa-europe', 'Master System', 'Wonder Boy (USA, Europe)', '1986', 'Platform', 'Sega', '1', 'Arcade', 'Side-scrolling platformer.', 'Rescue your girlfriend from the dark king.', 'The original high-speed island adventure.', 'Wonder Boy is a classic of momentum and timing. Ride your skateboard, throw stone hatchets, and eat fruit to stay alive as you race through islands and forests in this iconic Sega arcade port.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-iii---the-dragons-trap-usa-europe', 'Master System', 'Wonder Boy III - The Dragon''s Trap (USA, Europe)', '1989', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Break the curse by defeating the vampire dragon.', 'A masterpiece of non-linear 8-bit adventure.', 'Wonder Boy III: The Dragon''s Trap is one of the greatest games on the system. Transform into different animals—like Lizard-Man or Piranha-Man—to unlock new areas and defeat massive bosses.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-in-monster-land-usa-europe', 'Master System', 'Wonder Boy in Monster Land (USA, Europe)', '1988', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Restore the peace to Monster Land and find gold.', 'A deep blend of platforming and RPG mechanics.', 'Wonder Boy in Monster Land features a shop system where you buy better swords, shields, and magic. Navigate through levels, defeat hidden bosses, and uncover secrets in this foundational action-RPG.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-in-monster-world-europe', 'Master System', 'Wonder Boy in Monster World (Europe)', '1992', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Save Monster World from the evil BioMeka.', 'A high-quality 8-bit port of the legendary 16-bit RPG.', 'Wonder Boy in Monster World features vibrant redrawn graphics and deep adventure elements. Explore a sprawling interconnected world, buy equipment, and use magical spells to restore peace to the kingdom in this technical masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wonder-boy-in-monster-world-europe-beta', 'Master System', 'Wonder Boy in Monster World (Europe) (Beta)', '1992', 'Action', 'Sega', '1', 'Fantasy', 'Side-scrolling action RPG.', 'Save Monster World from the evil BioMeka.', 'Beta version of the sprawling action-RPG quest.', 'This Beta version of Wonder Boy in Monster World offers a rare look at the development of Shion’s adventure. Test the mechanics of the simplified 8-bit RPG systems and explore the refined level layouts of this Sega classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('woody-pop---shinjinrui-no-block-kuzushi-japan', 'Master System', 'Woody Pop - Shinjinrui no Block Kuzushi (Japan)', '1987', 'Puzzle', 'Sega', '1', 'Arcade', 'Ball and paddle puzzle.', 'Break all blocks using a ball and paddle.', 'A charming Japanese exclusive Breakout-style game.', 'Woody Pop: Shinjinrui no Block Kuzushi is a whimsical puzzle game featuring a tree spirit. Navigate through a non-linear mansion, choosing your path between 50 different levels in this polished and colorful 8-bit arcade title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-class-leader-board-europe', 'Master System', 'World Class Leader Board (Europe)', '1990', 'Sports', 'U.S. Gold', '1', 'Golf', 'Sports simulation (Golf).', 'Win on world-famous courses with the lowest score.', 'A professional and challenging golf simulator.', 'World Class Leader Board features legendary courses like St. Andrews and Doral. Master the intuitive power-bar system and account for wind and terrain in this realistic and highly-regarded 8-bit sports simulation.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-italia-90-europe', 'Master System', 'World Cup Italia ''90 (Europe)', '1990', 'Sports', 'Sega', '2', 'Soccer', 'Top-down sports simulation.', 'Win the 1990 World Cup with one of 30 nations.', 'The officially licensed game of the 1990 FIFA World Cup.', 'World Cup Italia ''90 features a bird''s-eye view of the pitch and a full tournament structure. Lead your favorite international team to victory in this fast-paced and historically accurate 8-bit soccer experience.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-cup-usa-94-europe-enfrdeesitnlptsv', 'Master System', 'World Cup USA 94 (Europe) (En,Fr,De,Es,It,Nl,Pt,Sv)', '1994', 'Sports', 'Sega', '4', 'Soccer', 'Top-down sports simulation.', 'Win the 1994 World Cup tournament in the USA.', 'The licensed 8-bit adaptation of the ''94 World Cup.', 'World Cup USA 94 features smooth, Sensible Soccer-style gameplay with small, fluid sprites. Navigate through the group stages and knockout rounds to lift the trophy in this vibrant and competitive late-gen title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-games-europe', 'Master System', 'World Games (Europe)', '1988', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Compete in diverse global athletic events.', 'A unique collection of international sports challenges.', 'World Games features unconventional events like the Caber Toss, Log Rolling, and Barrel Jumping. Test your timing and skill across multiple cultures in this fun and varied 8-bit sports anthology.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-games-europe-beta', 'Master System', 'World Games (Europe) (Beta)', '1988', 'Sports', 'Epyx', '4', 'Arcade', 'Multi-event sports simulation.', 'Compete in diverse global athletic events.', 'Beta version of the international sports collection.', 'This Beta build of World Games allows you to experience the diverse global events in their early development stages. Practice your technique in bull riding and cliff diving in this rare piece of Sega history.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-grand-prix-europe', 'Master System', 'World Grand Prix (Europe)', '1992', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Set the fastest lap and win the Grand Prix.', 'A technical and high-speed Formula One racer.', 'World Grand Prix focuses on precision driving and car maintenance. Race through various international circuits and use the built-in track editor to create your own racing challenges in this impressive 8-bit title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-grand-prix-usa', 'Master System', 'World Grand Prix (USA)', '1992', 'Racing', 'Sega', '1', 'Arcade', 'Behind-the-back racing.', 'Set the fastest lap and win the Grand Prix.', 'North American release of the Formula One sim.', 'Master the corners and outpace your rivals in World Grand Prix. This version features smooth scaling and a focus on realistic 8-bit physics, making it a favorite for fans of early professional racing games.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('world-soccer-world', 'Master System', 'World Soccer (World)', '1985', 'Sports', 'Sega', '2', 'Soccer', 'Top-down sports simulation.', 'Defeat international teams in a soccer tournament.', 'An early and influential 8-bit soccer game.', 'World Soccer features classic overhead gameplay and a specialized penalty shootout mode. Choose from eight international teams and lead them to glory in this foundational Sega sports title.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('wwf-wrestlemania---steel-cage-challenge-europe', 'Master System', 'WWF Wrestlemania - Steel Cage Challenge (Europe)', '1992', 'Wrestling', 'Ocean Software', '2', 'Arcade', 'Professional wrestling simulation.', 'Win the WWF Championship in a steel cage.', 'A high-stakes wrestling game with a heavy roster.', 'WWF Wrestlemania: Steel Cage Challenge features iconic wrestlers like Hulk Hogan and Bret Hart. Battle inside the ring or within the cage, utilizing grapples and strikes to pin your opponent in this intense 8-bit brawler.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('x-men---mojo-world-brazil', 'Master System', 'X-Men - Mojo World (Brazil)', '1996', 'Action', 'Sega', '1', 'Superhero', 'Side-scrolling action platformer.', 'Defeat Mojo and rescue the captured X-Men.', 'A rare Brazilian release based on the mutant saga.', 'X-Men: Mojo World features multiple playable characters, including Wolverine and Rogue. Use their unique mutant powers to navigate dangerous environments and defeat iconic Marvel villains in this late-era 8-bit adventure.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xenon-2---megablast-europe-image-works', 'Master System', 'Xenon 2 - Megablast (Europe) (Image Works)', '1989', 'Shooter', 'Image Works', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the Xenite bombs and their bio-organic fleet.', 'A visually stunning port of the Bitmap Brothers hit.', 'Xenon 2: Megablast features a gritty organic aesthetic and a deep upgrade shop. Navigate through alien tunnels and use the unique "reverse scroll" mechanic to survive this difficult and stylish 8-bit shmup.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('xenon-2---megablast-europe-virgin', 'Master System', 'Xenon 2 - Megablast (Europe) (Virgin)', '1989', 'Shooter', 'Virgin Interactive', '1', 'Arcade', 'Vertical scrolling shoot ''em up.', 'Destroy the Xenite bombs and their bio-organic fleet.', 'Virgin Games edition of the iconic sci-fi shooter.', 'Experience the intense action of Xenon 2. Armed with the Megablaster, fight through five levels of bio-mechanical horrors and massive bosses in this technically impressive conversion of the computer classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zaxxon-3-d-world', 'Master System', 'Zaxxon 3-D (World)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Behind-the-back 3D rail shooter.', 'Navigate the space fortress and defeat the robot.', 'A stereoscopic 3D version of the isometric classic.', 'Zaxxon 3-D uses Sega''s 3D Glasses to transform the iconic space shooter into a depth-defying rail adventure. Dodge obstacles and manage your altitude to survive the heavily defended enemy base.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zaxxon-3-d-world-beta', 'Master System', 'Zaxxon 3-D (World) (Beta)', '1987', 'Shooter', 'Sega', '1', 'Arcade', 'Behind-the-back 3D rail shooter.', 'Navigate the space fortress and defeat the robot.', 'Beta version of the stereoscopic 3D space shooter.', 'This Beta version of Zaxxon 3-D provides a look at the early implementation of 3D effects on the Master System. Test your flight skills and target accuracy in this rare 8-bit hardware showcase.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zillion-europe-v12', 'Master System', 'Zillion (Europe) (v1.2)', '1987', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling action adventure.', 'Infiltrate the Norsa base and rescue your team.', 'A deep, non-linear quest based on the anime series.', 'Zillion is a masterpiece of strategy and action. Use your Zillion laser to deactivate barriers and crack codes while exploring a massive underground complex in this influential 8-bit classic.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zillion-japan-europe-enja', 'Master System', 'Zillion (Japan, Europe) (En,Ja)', '1987', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling action adventure.', 'Infiltrate the Norsa base and rescue your team.', 'The original Japanese release of the sci-fi epic.', 'Experience the roots of the Zillion saga. With its unique blend of platforming and puzzle-solving, J.J.''s mission to rescue Apple and Champ remains a high point in the Master System''s library.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zillion-usa-v11', 'Master System', 'Zillion (USA) (v1.1)', '1987', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling action adventure.', 'Infiltrate the Norsa base and rescue your team.', 'Refined US version of the code-cracking adventure.', 'This v1.1 of Zillion features minor bug fixes and tweaks to the gameplay. Master the computer terminals and navigate the dangerous Norsa corridors in the most stable version of this sci-fi masterpiece.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zillion-ii---the-tri-formation-world', 'Master System', 'Zillion II - The Tri Formation (World)', '1988', 'Action', 'Sega', '1', 'Anime', 'Side-scrolling action & shmup.', 'Rescue your friends and defeat the Baron Ricks.', 'A high-octane sequel with transforming vehicles.', 'Zillion II: The Tri Formation shifts the focus to fast-paced action. Switch between platforming and high-speed motorcycle shooting stages as you pilot the Tri Formation to save your captured teammates.');
INSERT INTO juego_detalle (slug, plataforma, nombre, anio, genero, desarrollador, jugadores, estilo, gameplay, objetivo, descripcion_corta, descripcion_larga) VALUES ('zool---ninja-of-the-nth-dimension-europe', 'Master System', 'Zool - Ninja of the ''Nth'' Dimension (Europe)', '1992', 'Platform', 'Gremlin Interactive', '1', 'Cartoon', 'Side-scrolling platformer.', 'Save the "Nth" dimension from Krool''s army.', 'A high-speed, colorful ninja adventure.', 'Zool: Ninja of the ''Nth'' Dimension features incredibly fast-paced platforming and vibrant graphics. Clamber up walls and use ninja magic to defeat wacky enemies in this polished 8-bit port of the Amiga hit.');